local State = {
    failedAttempts = 0,
    lockedUntil = 0,
    lastRequestTime = 0,
    keyCache = {},
    blacklistedUsers = {},
    versionOk = true,
    latestVersion = CONFIG.CURRENT_VERSION,
    bgAsset = "",
}

local function debugLog(...)
    if CONFIG.DEBUG_MODE then
        print("[PawZHub Debug]", ...)
    end
end

local function generateToken()
    return game:GetService("HttpService"):GenerateGUID(false):gsub("-", ""):sub(1, 32)
end

local function getHWID()
    local UserInputService = game:GetService("UserInputService")
    local player = game:GetService("Players").LocalPlayer
    local components = {}

    pcall(function()
        local clientId = game:GetService("RbxAnalyticsService"):GetClientId()
        if clientId and clientId ~= "" then
            table.insert(components, clientId)
        end
    end)

    table.insert(components, string.format("%d:%d", player.UserId, player.AccountAge))

    local platform = "unknown"
    if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
        platform = "mobile"
    elseif UserInputService.KeyboardEnabled then
        platform = "pc"
    end
    table.insert(components, platform)

    local combined = table.concat(components, "|")
    local function hash(str)
        local h = 2166136261
        for i = 1, #str do
            h = bit32.bxor(h, string.byte(str, i))
            h = (h * 16777619) % 4294967296
        end
        return h
    end
    local hwid = string.format("%08X%08X", hash(combined), hash(combined .. "salt"))
    _G.PawZHub_HWID = hwid
    return hwid
end

local function detectKeyType(key)
    if not key or type(key) ~= "string" then return nil end
    key = key:match("^%s*(.-)%s*$") or key
    if key:match("^[a-f0-9]{24}$") then return "lifetime" end
    if key:match("^PAWZ%-[A-Z0-9]+%-[A-Z0-9]+%-[A-Z0-9]+$") then return "free" end
    return nil
end

local function normalizeKey(key)
    if not key or type(key) ~= "string" then return "" end
    key = key:match("^%s*(.-)%s*$") or key
    if key:match("^[a-fA-F0-9]{24}$") then return key:lower() end
    return key:upper()
end

local function checkRateLimit()
    local now = os.time()
    if now - State.lastRequestTime < CONFIG.RATE_LIMIT_COOLDOWN then
        return false, "Please wait a moment"
    end
    State.lastRequestTime = now
    return true
end

local function checkLockout()
    if State.lockedUntil > os.time() then
        return false, "Locked for " .. (State.lockedUntil - os.time()) .. "s"
    end
    if State.lockedUntil > 0 and State.lockedUntil <= os.time() then
        State.failedAttempts = 0
        State.lockedUntil = 0
    end
    return true
end

local function registerFailedAttempt()
    State.failedAttempts = State.failedAttempts + 1
    if State.failedAttempts >= CONFIG.MAX_RETRY_ATTEMPTS then
        State.lockedUntil = os.time() + CONFIG.LOCKOUT_DURATION
        return true, CONFIG.LOCKOUT_DURATION
    end
    return false, 0
end

local function fetchBlacklist()
    pcall(function()
        local resp = game:GetService("HttpService"):GetAsync(CONFIG.BLACKLIST_URL, true)
        local data = game:GetService("HttpService"):JSONDecode(resp)
        State.blacklistedUsers = data.users or data or {}
    end)
end

local function isBlacklisted(userId)
    for _, id in ipairs(State.blacklistedUsers) do
        if tostring(id) == tostring(userId) then return true end
    end
    return false
end

local function checkVersion()
    pcall(function()
        local resp = game:GetService("HttpService"):GetAsync(CONFIG.VERSION_CHECK_URL, true)
        local data = game:GetService("HttpService"):JSONDecode(resp)
        if data and data.version then
            State.latestVersion = tostring(data.version)
            if data.minVersion and data.minVersion > CONFIG.CURRENT_VERSION then
                State.versionOk = false
            end
            if data.forceUpdate then State.versionOk = false end
        end
    end)
end

local function sendWebhook(payload)
    if not CONFIG.WEBHOOK_URL or CONFIG.WEBHOOK_URL == "" then return end
    pcall(function()
        local HttpService = game:GetService("HttpService")
        HttpService:PostAsync(CONFIG.WEBHOOK_URL, HttpService:JSONEncode(payload), Enum.HttpContentType.ApplicationJson)
    end)
end

local function verifyKeyOffline(key)
    local testKeys = {
        ["PAWZ-FREE-2024-DEMO1"] = { type = "free", tier = "free", expiry = nil, features = {"basic"} },
        ["PAWZ-FREE-TEST-KEY1"] = { type = "free", tier = "free", expiry = nil, features = {"basic"} },
        ["PAWZ-PREM-2024-TEST"] = {
            type = "free", tier = "premium",
            expiry = os.time() + (30 * 24 * 3600),
            features = {"basic", "advanced"},
        },
        ["PAWZ-LIFE-2024-VIP1"] = {
            type = "free", tier = "lifetime", expiry = nil,
            features = {"basic", "advanced", "premium", "exclusive"},
        },
        ["f03d3260914a9475faf29b12"] = {
            type = "lifetime", tier = "lifetime", expiry = nil,
            features = {"basic", "advanced", "premium", "exclusive"},
            hwidResetAvailable = true,
        },
    }
    local keyData = testKeys[key]
    if keyData then
        if keyData.expiry and os.time() > keyData.expiry then
            return false, "Key expired", nil
        end
        return true, "Valid (offline mode)", keyData
    end
    return false, "Invalid key"
end

local function verifyKeyRemote(key)
    local canProceed, msg = checkRateLimit()
    if not canProceed then return false, msg end
    local lockOk, lockMsg = checkLockout()
    if not lockOk then return false, lockMsg end

    local player = game:GetService("Players").LocalPlayer
    if isBlacklisted(player.UserId) then
        return false, "Account blacklisted"
    end

    local cached = State.keyCache[key]
    if cached and (os.time() - cached.ts) < CONFIG.CACHE_DURATION then
        return true, "Valid (cached)", cached.data
    end

    local HttpService = game:GetService("HttpService")
    local requestData = {
        key = key,
        hwid = getHWID(),
        userId = player.UserId,
        username = player.Name,
        displayName = player.DisplayName,
        gameId = game.PlaceId,
        version = CONFIG.CURRENT_VERSION,
        timestamp = os.time(),
        executor = (_G.PawZHub_Executor and _G.PawZHub_Executor.name) or "Unknown",
    }

    local success, response = pcall(function()
        return HttpService:PostAsync(
            CONFIG.KEY_CHECK_URL,
            HttpService:JSONEncode(requestData),
            Enum.HttpContentType.ApplicationJson,
            false,
            { ["Content-Type"] = "application/json" }
        )
    end)

    if success then
        local data = HttpService:JSONDecode(response)
        if data.valid then
            State.keyCache[key] = { data = data, ts = os.time() }
            State.failedAttempts = 0
            State.lockedUntil = 0
            sendWebhook({
                type = "key_success",
                userId = player.UserId,
                username = player.Name,
                keyType = detectKeyType(key),
                hwid = getHWID(),
            })
            return true, data.message or "Valid", data
        else
            sendWebhook({
                type = "key_fail",
                userId = player.UserId,
                username = player.Name,
                message = data.message,
            })
            return false, data.message or "Invalid key"
        end
    else
        if CONFIG.ALLOW_OFFLINE_MODE then
            return verifyKeyOffline(key)
        end
        return false, "Server unreachable"
    end
end

function CheckKeySystem.requestHWIDReset(key)
    key = normalizeKey(key)
    local HttpService = game:GetService("HttpService")
    local success, response = pcall(function()
        return HttpService:PostAsync(
            CONFIG.HWID_RESET_URL,
            HttpService:JSONEncode({
                key = key,
                hwid = getHWID(),
                userId = game:GetService("Players").LocalPlayer.UserId,
            }),
            Enum.HttpContentType.ApplicationJson
        )
    end)
    if success then
        local data = HttpService:JSONDecode(response)
        return data.success, data.message
    end
    return false, "Server unreachable"
end

local function createSession(key, keyData)
    local token = generateToken()
    local hwid = getHWID()
    local player = game:GetService("Players").LocalPlayer
    local gameName = "Unknown"
    pcall(function()
        gameName = game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId).Name
    end)

    local sessionData = {
        token = token,
        key = key,
        keyType = detectKeyType(key) or (keyData and keyData.type) or "free",
        hwid = hwid,
        timestamp = os.time(),
        expiresAt = os.time() + CONFIG.SESSION_DURATION,
        gameId = game.PlaceId,
        gameName = gameName,
        userId = player.UserId,
        username = player.Name,
        keyTier = keyData and keyData.tier or "free",
        keyExpiry = keyData and keyData.expiry or nil,
        keyFeatures = keyData and keyData.features or {},
        sessionId = generateToken():sub(1, 16),
    }

    _G.PawZHubSession = sessionData
    _G.PawZHub_Token = token
    _G.PawZHub_Authenticated = true
    debugLog("Session created:", sessionData.sessionId, "Type:", sessionData.keyType)
    return sessionData
end

function CheckKeySystem.verifySession()
    if not _G.PawZHubSession then return false, "No session" end
    local session = _G.PawZHubSession
    if os.time() > session.expiresAt then
        CheckKeySystem.destroySession()
        return false, "Session expired"
    end
    if session.gameId ~= game.PlaceId then return false, "Wrong game" end
    if CONFIG.ENABLE_HWID_BINDING and session.hwid ~= getHWID() then
        CheckKeySystem.destroySession()
        return false, "HWID mismatch"
    end
    return true, session
end

function CheckKeySystem.destroySession()
    _G.PawZHubSession = nil
    _G.PawZHub_Token = nil
    _G.PawZHub_Authenticated = nil
end

function CheckKeySystem.extendSession(extraSeconds)
    local valid, session = CheckKeySystem.verifySession()
    if not valid then return false end
    session.expiresAt = os.time() + (extraSeconds or CONFIG.SESSION_DURATION)
    return true
end

local function detectExecutor()
    local info = { name = "Unknown", platform = "Unknown" }
    if syn or is_syn_env then
        info.name, info.platform = "Synapse X", "PC"
    elseif KRNL_LOADED then
        info.name, info.platform = "KRNL", "PC"
    elseif identifyexecutor then
        local ok, name = pcall(identifyexecutor)
        info.name = ok and name or "Unknown"
        info.platform = "PC"
    elseif APPLETOUCHHOOK_LOADED then
        info.name, info.platform = "Delta", "iOS"
    elseif FLUX_LOADED then
        info.name, info.platform = "Flux", "iOS"
    elseif Arceus then
        info.name, info.platform = "Arceus X", "Android"
    elseif hydrogen then
        info.name, info.platform = "Hydrogen", "Android"
    else
        local UIS = game:GetService("UserInputService")
        if UIS.TouchEnabled and not UIS.KeyboardEnabled then
            info.name, info.platform = "Mobile", "Mobile"
        elseif UIS.KeyboardEnabled then
            info.name, info.platform = "PC Executor", "PC"
        end
    end
    _G.PawZHub_Executor = info
    return info
end

-- Decode + cache background asset
local function ensureBackgroundAsset()
    if State.bgAsset ~= "" then return State.bgAsset end
    if type(BG_B64) ~= "string" or #BG_B64 < 100 then return "" end

    local raw
    pcall(function()
        if crypt and crypt.base64decode then
            raw = crypt.base64decode(BG_B64)
        elseif base64 and base64.decode then
            raw = base64.decode(BG_B64)
        elseif syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode then
            raw = syn.crypt.base64.decode(BG_B64)
        end
    end)

    if not raw then
        -- minimal fallback decoder
        pcall(function()
            local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
            local data = BG_B64:gsub("[^" .. b .. "=]", "")
            local t = {}
            for i = 1, #data, 4 do
                local n = (b:find(data:sub(i, i)) or 1) - 1
                local n2 = (b:find(data:sub(i + 1, i + 1)) or 1) - 1
                local n3 = (b:find(data:sub(i + 2, i + 2)) or 1) - 1
                local n4 = (b:find(data:sub(i + 3, i + 3)) or 1) - 1
                local v = n * 262144 + n2 * 4096 + n3 * 64 + n4
                t[#t + 1] = string.char(
                    math.floor(v / 65536) % 256,
                    math.floor(v / 256) % 256,
                    v % 256
                )
            end
            local pad = 0
            if data:sub(-1) == "=" then pad = pad + 1 end
            if data:sub(-2, -2) == "=" then pad = pad + 1 end
            raw = table.concat(t):sub(1, #t * 3 - pad)
        end)
    end

    if not raw then return "" end

    pcall(function()
        if isfolder and not isfolder("PawZHub") then makefolder("PawZHub") end
        local path = "PawZHub/key_bg.jpg"
        if writefile then writefile(path, raw) end
        if getcustomasset then
            State.bgAsset = getcustomasset(path)
        elseif getsynasset then
            State.bgAsset = getsynasset(path)
        end
    end)

    return State.bgAsset
end

local function CreateElement(className, props)
    local obj = Instance.new(className)
    for k, v in pairs(props or {}) do
        if k ~= "Parent" then obj[k] = v end
    end
    if props and props.Parent then obj.Parent = props.Parent end
    return obj
end

local function AddCorner(parent, radius)
    local c = Instance.new("UICorner")
    c.CornerRadius = UDim.new(0, radius or 16)  -- Tăng default 12 → 16
    c.Parent = parent
    return c
end

local function AddStroke(parent, color, thickness, transparency)
    local s = Instance.new("UIStroke")
    s.Color = color or Theme.inputBorder
    s.Thickness = thickness or 1
    s.Transparency = transparency or 0.3
    s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    s.Parent = parent
    return s
end

