        BackgroundTransparency = 1,
        Text = "🔑",
        TextSize = 14,
        ZIndex = 12,
        Parent = inputCard,
    })
    
    -- Rotate animation cho key icon
    task.spawn(function()
        while keyIcon and keyIcon.Parent do
            for i = 0, 360, 10 do
                if not keyIcon or not keyIcon.Parent then break end
                keyIcon.Rotation = i
                task.wait(0.05)
            end
        end
    end)

    local input = CreateElement("TextBox", {
        Size = UDim2.new(1, -48, 1, 0),
        Position = UDim2.new(0, 38, 0, 0),
        BackgroundTransparency = 1,
        Text = "",
        PlaceholderText = "Enter Key here..",
        TextColor3 = Theme.text,
        PlaceholderColor3 = Theme.textMuted,
        TextSize = 13,
        Font = Enum.Font.Gotham,
        ClearTextOnFocus = false,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 12,
        Parent = inputCard,
    })

    input.Focused:Connect(function()
        TweenService:Create(inputStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Color = Theme.accentSoft,
            Transparency = 0.05,
            Thickness = 2,
        }):Play()
        TweenService:Create(inputCard, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            BackgroundTransparency = 0.05,
            Size = UDim2.new(1, 2, 0, 44),
        }):Play()
    end)
    input.FocusLost:Connect(function()
        TweenService:Create(inputStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Color = Theme.inputBorder,
            Transparency = 0.4,
            Thickness = 1,
        }):Play()
        TweenService:Create(inputCard, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            BackgroundTransparency = 0.15,
            Size = UDim2.new(1, 0, 0, 42),
        }):Play()
    end)

    -- Buttons row: Get Key | Verify Key
    local btnRow = CreateElement("Frame", {
        Size = UDim2.new(1, 0, 0, 38),
        Position = UDim2.new(0, 0, 0, 116),
        BackgroundTransparency = 1,
        ZIndex = 11,
        Parent = content,
    })

    local getKeyBtn = CreateElement("TextButton", {
        Size = UDim2.new(0.48, -4, 1, 0),
        Position = UDim2.new(0, 0, 0, 0),
        BackgroundColor3 = Theme.btn,
        BackgroundTransparency = 0.05,
        Text = "Get Key",
        TextColor3 = Theme.text,
        TextSize = 13,
        Font = Enum.Font.GothamBold,
        AutoButtonColor = false,
        ZIndex = 12,
        Parent = btnRow,
    })
    AddCorner(getKeyBtn, 22)  -- Bo tròn button hơn

    local submitBtn = CreateElement("TextButton", {
        Size = UDim2.new(0.48, -4, 1, 0),
        Position = UDim2.new(0.52, 4, 0, 0),
        BackgroundColor3 = Theme.btn,
        BackgroundTransparency = 0.05,
        Text = "Verify Key",
        TextColor3 = Theme.text,
        TextSize = 13,
        Font = Enum.Font.GothamBold,
        AutoButtonColor = false,
        ZIndex = 12,
        Parent = btnRow,
    })
    AddCorner(submitBtn, 22)  -- Bo tròn giống getKeyBtn

    local function hoverBtn(btn)
        local originalSize = btn.Size
        btn.MouseEnter:Connect(function()
            TweenService:Create(btn, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                BackgroundColor3 = Theme.btnHover,
            }):Play()
        end)
        btn.MouseLeave:Connect(function()
            TweenService:Create(btn, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                BackgroundColor3 = Theme.btn,
            }):Play()
        end)
    end
    hoverBtn(getKeyBtn)
    hoverBtn(submitBtn)

    -- HWID reset (lifetime)
    local resetBtn = CreateElement("TextButton", {
        Size = UDim2.new(1, 0, 0, 28),
        Position = UDim2.new(0, 0, 0, 162),
        BackgroundColor3 = Theme.warning,
        Text = "Reset HWID · Lifetime only",
        TextColor3 = Color3.new(1, 1, 1),
        TextSize = 11,
        Font = Enum.Font.GothamMedium,
        AutoButtonColor = false,
        Visible = false,
        ZIndex = 12,
        Parent = content,
    })
    AddCorner(resetBtn, 22)  -- Bo tròn giống các button khác

    -- Status
    local status = CreateElement("TextLabel", {
        Size = UDim2.new(1, 0, 0, 16),
        Position = UDim2.new(0, 0, 0, 196),
        BackgroundTransparency = 1,
        Text = "",
        TextColor3 = Theme.danger,
        TextSize = 11,
        Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Center,
        ZIndex = 12,
        Parent = content,
    })

    -- Premium hint
    CreateElement("TextLabel", {
        Size = UDim2.new(1, 0, 0, 14),
        Position = UDim2.new(0, 0, 1, -78),
        BackgroundTransparency = 1,
        Text = "Tired of free keys? Get Lifetime access!",
        TextColor3 = Theme.textSub,
        TextSize = 11,
        Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Center,
        ZIndex = 12,
        Parent = content,
    })

    -- Gold CTA
    local premiumBtn = CreateElement("TextButton", {
        Size = UDim2.new(1, 0, 0, 40),
        Position = UDim2.new(0, 0, 1, -48),  -- Giảm từ -56 → -48 (gần hơn 8px)
        BackgroundColor3 = Theme.gold,
        Text = "Join Discord · Lifetime Keys",
        TextColor3 = Color3.fromRGB(40, 30, 10),
        TextSize = 13,
        Font = Enum.Font.GothamBold,
        AutoButtonColor = false,
        ZIndex = 12,
        Parent = content,
    })
    AddCorner(premiumBtn, 22)  -- Bo tròn Discord button

    premiumBtn.MouseEnter:Connect(function()
        TweenService:Create(premiumBtn, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
            BackgroundColor3 = Color3.fromRGB(255, 230, 130),
            Size = UDim2.new(1, 4, 0, 44),
        }):Play()
    end)
    premiumBtn.MouseLeave:Connect(function()
        TweenService:Create(premiumBtn, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            BackgroundColor3 = Theme.gold,
            Size = UDim2.new(1, 0, 0, 40),
        }):Play()
    end)

    premiumBtn.MouseButton1Click:Connect(function()
        if setclipboard then
            setclipboard(CONFIG.DISCORD_URL)
            premiumBtn.Text = "✓  Discord link copied!"
            task.wait(1.5)
            premiumBtn.Text = "Join Discord · Lifetime Keys"
        else
            status.Text = CONFIG.DISCORD_URL
            status.TextColor3 = Theme.accentSoft
        end
    end)
    
    -- Thêm pulse animation cho Premium button
    task.spawn(function()
        while premiumBtn and premiumBtn.Parent do
            TweenService:Create(premiumBtn, TweenInfo.new(1.5, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut), {
                BackgroundColor3 = Color3.fromRGB(255, 230, 120),
            }):Play()
            task.wait(1.5)
            TweenService:Create(premiumBtn, TweenInfo.new(1.5, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut), {
                BackgroundColor3 = Theme.gold,
            }):Play()
            task.wait(1.5)
        end
    end)

    -- Actions
    getKeyBtn.MouseButton1Click:Connect(function()
        if setclipboard then
            setclipboard(CONFIG.GET_KEY_URL)
            getKeyBtn.Text = "✓  Link Copied!"
            status.Text = "Get-key link copied to clipboard"
            status.TextColor3 = Theme.success
            task.wait(1.6)
            getKeyBtn.Text = "Get Key"
            status.Text = ""
        else
            status.Text = CONFIG.GET_KEY_URL
            status.TextColor3 = Theme.accentSoft
        end
    end)

    resetBtn.MouseButton1Click:Connect(function()
        local key = normalizeKey(input.Text)
        if detectKeyType(key) ~= "lifetime" then
            status.Text = "Enter a 24-char lifetime key first"
            status.TextColor3 = Theme.warning
            return
        end
        resetBtn.Text = "Resetting..."
        local ok, msg = CheckKeySystem.requestHWIDReset(key)
        if ok then
            status.Text = "HWID reset — key ready on new device"
            status.TextColor3 = Theme.success
            resetBtn.Text = "Reset complete"
            task.wait(1.8)
            resetBtn.Visible = false
        else
            status.Text = msg or "Reset failed"
            status.TextColor3 = Theme.danger
            resetBtn.Text = "Reset HWID · Lifetime only"
        end
    end)

    local function setStatus(text, color)
        status.Text = text or ""
        status.TextColor3 = color or Theme.danger
    end

    local function shake(obj)
        local orig = obj.Position
        for _, ox in ipairs({7, -7, 4, -4, 0}) do
            TweenService:Create(obj, TweenInfo.new(0.04), {
                Position = orig + UDim2.new(0, ox, 0, 0),
            }):Play()
            task.wait(0.04)
        end
        obj.Position = orig
    end

    local function doVerify()
        local key = normalizeKey(input.Text)
        if not key or #key < 5 then
            setStatus("Please enter a valid key", Theme.danger)
            shake(inputCard)
            return
        end

        local lockOk, lockMsg = checkLockout()
        if not lockOk then
            setStatus(lockMsg, Theme.warning)
            return
        end

        resetBtn.Visible = (detectKeyType(key) == "lifetime")
        submitBtn.Text = "  ⟳  Verifying..."
        setStatus("Checking key...", Theme.textMuted)

        task.spawn(function()
            local valid, message, keyData = verifyKeyRemote(key)
            if valid then
                submitBtn.Text = "  ✓  Success"
                TweenService:Create(submitBtn, TweenInfo.new(0.15), {
                    BackgroundColor3 = Theme.success,
                }):Play()
                setStatus("Access granted — loading...", Theme.success)
                task.wait(0.65)
                local session = createSession(key, keyData)
                TweenService:Create(window, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
                    Size = UDim2.new(0, 0, 0, 0),
                    BackgroundTransparency = 1,
                }):Play()
                TweenService:Create(dim, TweenInfo.new(0.25), { BackgroundTransparency = 1 }):Play()
                task.wait(0.25)
                screenGui:Destroy()
                if callback then callback(true, session) end
            else
                submitBtn.Text = "  ✗  Failed"
                TweenService:Create(submitBtn, TweenInfo.new(0.12), {
                    BackgroundColor3 = Theme.danger,
                }):Play()
                shake(window)
                local locked, waitSec = registerFailedAttempt()
                if locked then
                    setStatus("Too many attempts — wait " .. waitSec .. "s", Theme.warning)
                else
                    setStatus(message or "Invalid key", Theme.danger)
                end
                task.wait(1.1)
                submitBtn.Text = "  ⟳  Verify Key"
                TweenService:Create(submitBtn, TweenInfo.new(0.15), {
                    BackgroundColor3 = Theme.btn,
                }):Play()
            end
        end)
    end

    submitBtn.MouseButton1Click:Connect(doVerify)
    input.FocusLost:Connect(function(enter)
        if enter then doVerify() end
    end)
    input:GetPropertyChangedSignal("Text"):Connect(function()
        resetBtn.Visible = (detectKeyType(normalizeKey(input.Text)) == "lifetime")
    end)

    -- Drag from brand area
    local dragging, dragStart, startPos = false, nil, nil
    brandRow.InputBegan:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1
            or inp.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragStart = inp.Position
            startPos = window.Position
        end
    end)
    brandRow.InputEnded:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1
            or inp.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end)
    UserInputService.InputChanged:Connect(function(inp)
        if dragging and (inp.UserInputType == Enum.UserInputType.MouseMovement
            or inp.UserInputType == Enum.UserInputType.Touch) then
            local delta = inp.Position - dragStart
            window.Position = UDim2.new(
                startPos.X.Scale, startPos.X.Offset + delta.X,
                startPos.Y.Scale, startPos.Y.Offset + delta.Y
            )
        end
    end)

    -- Entry animation với bounce effect mạnh hơn
    window.Size = UDim2.new(0, WIN_W * 0.85, 0, WIN_H * 0.85)
    window.BackgroundTransparency = 0.5
    dim.BackgroundTransparency = 1
    TweenService:Create(dim, TweenInfo.new(0.35, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundTransparency = 0.45 }):Play()
    TweenService:Create(window, TweenInfo.new(0.5, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
        Size = UDim2.new(0, WIN_W, 0, WIN_H),
        BackgroundTransparency = 0,
    }):Play()
end

-- ============================================
-- PUBLIC API
-- ============================================

function CheckKeySystem.show(callback)
    task.spawn(function()
        fetchBlacklist()
        checkVersion()
    end)
    createKeyUI(callback, detectExecutor())
end

function CheckKeySystem.hasFeature(featureName)
    local valid, session = CheckKeySystem.verifySession()
    if not valid then return false end
    for _, f in ipairs(session.keyFeatures or {}) do
        if f == featureName then return true end
    end
    return false
end

function CheckKeySystem.getKeyType()
    local valid, session = CheckKeySystem.verifySession()
    if not valid then return nil end
    return session.keyType
end

function CheckKeySystem.getSession()
    local valid, session = CheckKeySystem.verifySession()
    if not valid then return nil end
    return session
end

function CheckKeySystem.isAuthenticated()
    return CheckKeySystem.verifySession()
end

function CheckKeySystem.getHWID()
    return getHWID()
end

function CheckKeySystem.getConfig()
    return CONFIG
end

return CheckKeySystem
